import{_ as e,o as d,c as o,ag as r}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Keyboard Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"sheets/keyboard-shortcuts.md","filePath":"sheets/keyboard-shortcuts.md"}'),c={name:"sheets/keyboard-shortcuts.md"};function a(i,t,n,l,h,s){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><p>Keyboard shortcuts for common actions. <code>Ctrl</code> is the modifier on Windows/Linux and <code>⌘</code> on Mac — either one works wherever both are listed.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Press <code>Ctrl+/</code> / <code>⌘+/</code> in the spreadsheet to open the <strong>Keyboard shortcuts</strong> dialog. It&#39;s a hand-maintained summary of the most common bindings, so it is shorter than this page — a shortcut listed here but missing from the dialog (<code>F4</code>, the in-cell <code>Alt+Enter</code>, <code>Space</code>, <code>Alt+↓</code>, and <code>Tab</code> while editing) still works.</p></div><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Move the active cell</td><td>Arrow keys</td></tr><tr><td>Jump to the edge of the data</td><td><code>Ctrl+Arrow</code> / <code>⌘+Arrow</code></td></tr><tr><td>Move to the next cell</td><td><code>Tab</code></td></tr><tr><td>Move to the previous cell</td><td><code>Shift+Tab</code></td></tr></tbody></table><h2 id="selection" tabindex="-1">Selection <a class="header-anchor" href="#selection" aria-label="Permalink to &quot;Selection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Select all</td><td><code>Ctrl+A</code> / <code>⌘+A</code></td></tr><tr><td>Extend the selection by one cell</td><td><code>Shift+Arrow</code></td></tr><tr><td>Select an entire row</td><td>Click the row number</td></tr><tr><td>Select an entire column</td><td>Click the column header</td></tr><tr><td>Extend a row/column selection</td><td><code>Shift</code>-click another header</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>Shift+Arrow</code> extends the selection <strong>one cell at a time</strong>. Adding <code>Ctrl</code> / <code>⌘</code> does not extend the selection to the edge of the data — the combination still extends by a single cell.</p></div><h2 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Start editing the active cell</td><td><code>Enter</code>, or just start typing</td></tr><tr><td>Confirm the entry and move down</td><td><code>Enter</code> (while editing)</td></tr><tr><td>Confirm the entry and move right / left</td><td><code>Tab</code> / <code>Shift+Tab</code> (while editing)</td></tr><tr><td>Cancel editing</td><td><code>Escape</code></td></tr><tr><td>Insert a line break inside a cell</td><td><code>Alt+Enter</code></td></tr><tr><td>Clear cell contents</td><td><code>Delete</code> / <code>Backspace</code></td></tr><tr><td>Cycle a formula reference between relative and absolute</td><td><code>F4</code> (while editing)</td></tr><tr><td>Toggle a checkbox</td><td><code>Space</code></td></tr><tr><td>Open a dropdown list</td><td><code>Alt+↓</code></td></tr><tr><td>Merge / unmerge the selection</td><td><code>Ctrl+Shift+M</code> / <code>⌘+Shift+M</code></td></tr><tr><td>Undo</td><td><code>Ctrl+Z</code> / <code>⌘+Z</code></td></tr><tr><td>Redo</td><td><code>Ctrl+Y</code> / <code>⌘+Shift+Z</code></td></tr></tbody></table><p><code>Enter</code> does two different things depending on the selection. On a single cell it opens the editor. With a multi-cell range selected it moves the active cell down within that range instead (<code>Shift+Enter</code> moves up), so you can walk a block without leaving it.</p><p><code>Space</code> and <code>Alt+↓</code> only apply to cells covered by a data validation rule — a checkbox rule for <code>Space</code>, a dropdown rule for <code>Alt+↓</code>. See <a href="./data-validation.html">Data Validation</a>.</p><p>In the in-cell editor, <code>Ctrl+Enter</code> / <code>⌘+Enter</code> also inserts a line break. It exists because the macOS Korean IME reserves <code>Option</code> for Hanja conversion; in the formula bar, use <code>Alt+Enter</code>.</p><h2 id="clipboard" tabindex="-1">Clipboard <a class="header-anchor" href="#clipboard" aria-label="Permalink to &quot;Clipboard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Copy</td><td><code>Ctrl+C</code> / <code>⌘+C</code></td></tr><tr><td>Cut</td><td><code>Ctrl+X</code> / <code>⌘+X</code></td></tr><tr><td>Paste</td><td><code>Ctrl+V</code> / <code>⌘+V</code></td></tr><tr><td>Clear the copy marquee</td><td><code>Escape</code></td></tr></tbody></table><h2 id="formatting" tabindex="-1">Formatting <a class="header-anchor" href="#formatting" aria-label="Permalink to &quot;Formatting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Bold</td><td><code>Ctrl+B</code> / <code>⌘+B</code></td></tr><tr><td>Italic</td><td><code>Ctrl+I</code> / <code>⌘+I</code></td></tr><tr><td>Underline</td><td><code>Ctrl+U</code> / <code>⌘+U</code></td></tr><tr><td>Strikethrough</td><td><code>Ctrl+Shift+S</code> / <code>⌘+Shift+S</code></td></tr></tbody></table><h2 id="find-comments-and-help" tabindex="-1">Find, Comments, and Help <a class="header-anchor" href="#find-comments-and-help" aria-label="Permalink to &quot;Find, Comments, and Help&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Shortcut</th></tr></thead><tbody><tr><td>Find</td><td><code>Ctrl+F</code> / <code>⌘+F</code></td></tr><tr><td>Comment on the active cell</td><td><code>Ctrl+Alt+M</code> / <code>⌘+Alt+M</code></td></tr><tr><td>Toggle the comments panel</td><td><code>Ctrl+Alt+Shift+M</code> / <code>⌘+Alt+Shift+M</code></td></tr><tr><td>Show keyboard shortcuts</td><td><code>Ctrl+/</code> / <code>⌘+/</code></td></tr></tbody></table>',19)])])}const m=e(c,[["render",a]]);export{u as __pageData,m as default};
